  // 마디마다 길 위 자리와 방향
  const pts=SPINE.map(S=>{ const p=crwTrailAt(TR,S.s,new THREE.Vector3()); p.y=crwGround(p.x,p.z)+S.y0; return p; });
  const neck=2;                                // Bone_012 — 머리는 여기를 축으로 돈다
  const np=pts[neck];
  const bodyYaw=Math.atan2(pts[1].x-pts[3].x,pts[1].z-pts[3].z);
  let ly=Math.atan2(tx-np.x,tz-np.z)-bodyYaw;
  while(ly>Math.PI)ly-=6.2832; while(ly<-Math.PI)ly+=6.2832;
